def test_total_variation_distance_for_identical_counts_is_zero():
    counts = {"00": 60, "11": 40}
    assert total_variation_distance(counts, counts) == pytest.approx(0.0)


def test_total_variation_distance_for_shifted_binary_counts():
    left = {"0": 75, "1": 25}
    right = {"0": 25, "1": 75}
    assert total_variation_distance(left, right) == pytest.approx(0.5)


def test_hellinger_and_js_divergence_for_disjoint_distributions():
    left = {"0": 100}
    right = {"1": 100}

    assert hellinger_distance(left, right) == pytest.approx(1.0)
    assert jensen_shannon_divergence(left, right) == pytest.approx(1.0)


