def calculate_average_qber(self) -> float:
    """Calculate average QBER across valid jobs."""
    valid = _valid_jobs(self.job_results)
    if not valid:
        return 1.0
    return float(np.mean([j.error_rate for j in valid]))

    def get_fidelity_trend(self) -> dict[str, list]:
        """Get fidelity trend over time from valid jobs."""
        valid = _valid_jobs(self.job_results)
        if not valid:
            return {"timestamps": [], "fidelities": []}

        sorted_jobs = sorted(valid, key=lambda j: j.created)

        return {
            "timestamps": [j.created.isoformat() for j in sorted_jobs],
            "fidelities": [j.process_fidelity for j in sorted_jobs],
        }

    def get_backend_comparison_chart_data(self) -> dict:
        """Get data for backend comparison chart."""
        if not self.backend_comparison:
            return {"backends": [], "fidelities": [], "error_rates": [], "valid_counts": []}

        backends = []
        fidelities = []
        error_rates = []
        valid_counts = []

        for backend, stats in sorted(self.backend_comparison.items()):
            if stats["valid_job_count"] == 0:
                continue
            backends.append(backend)
            fidelities.append(stats["avg_fidelity"])
            error_rates.append(stats["avg_error_rate"])
            valid_counts.append(stats["valid_job_count"])

        return {
            "backends": backends,
            "fidelities": fidelities,
            "error_rates": error_rates,
            "valid_counts": valid_counts,
        }

    def get_circuit_type_breakdown(self) -> dict[str, dict]:
        """Summarize results by inferred circuit type."""
        breakdown: dict[str, dict[str, Any]] = {}
        for job in _valid_jobs(self.job_results):
            ctype = job.circuit_type
            if ctype not in breakdown:
                breakdown[ctype] = {"count": 0, "fidelities": [], "backends": set()}
            breakdown[ctype]["count"] += 1
            breakdown[ctype]["fidelities"].append(job.process_fidelity)
            breakdown[ctype]["backends"].add(job.backend)

        return {
            ctype: {
                "count": info["count"],
                "avg_fidelity": float(np.mean(info["fidelities"])),
                "backends": sorted(info["backends"]),
            }
            for ctype, info in breakdown.items()
        }

    def generate_security_audit_data(self) -> dict:
        """Generate security audit data from real quantum results."""
        valid = _valid_jobs(self.job_results)
        if not valid:
            return {
                "overall_score": 0,
                "fidelity_score": 0,
                "error_rate_score": 0,
                "backend_reliability": 0,
            }

        avg_fidelity = self.calculate_average_fidelity()
        avg_error = self.calculate_average_qber()

        # Clamp to [0, 1] before converting to a 0-100 score.
        fidelity_score = max(0.0, min(1.0, avg_fidelity)) * 100
        error_score = max(0.0, min(1.0, 1 - avg_error)) * 100

        if len(valid) > 1:
            fidelity_std = np.std([j.process_fidelity for j in valid])
            reliability = max(0.0, 100 - fidelity_std * 1000)
        else:
            reliability = 50.0

        overall_score = fidelity_score * 0.4 + error_score * 0.4 + reliability * 0.2

        return {
            "overall_score": overall_score,
            "fidelity_score": fidelity_score,
            "error_rate_score": error_score,
            "backend_reliability": reliability,
            "total_jobs": len(self.job_results),
            "valid_jobs": len(valid),
            "total_shots": sum(j.shots for j in valid),
            "backends_used": len(self.backend_comparison),
            "best_backend": self.get_best_backend(),
            "circuit_breakdown": self.get_circuit_type_breakdown(),
        }


