          throw new Error(`Failed to load DNA circuit ${selectedCircuitId}`)
        }

        const data = (await res.json()) as DNACircuitDetailResponse
        setSelectedCircuit(data.circuit)
        setCircuitPreview(data.preview)
      } catch (fetchError) {
        console.error(fetchError)
        setError(`Failed to load circuit details for ${selectedCircuitId}.`)
      } finally {
        setLoadingCircuit(false)
      }
    }

    fetchCircuitDetail()
