        return None
    configured_path = self.config.runtime.llama_cpp.executable_path
    if not configured_path:
        return None
    path = Path(configured_path)
    if not path.is_absolute():
        path = (self.root / path).resolve()
    if path.exists() and path.is_file():
        return path
    return None

