def _interpret_steane_syndrome(
    syndrome_bits: list[int],
) -> dict[str, int | str | list[int]]:
    """Interpret syndrome measurement bits for Steane's code."""
    if all(s == 0 for s in syndrome_bits):
        error_type = "none"
        error_qubit = -1
    elif syndrome_bits[0] == 1 and syndrome_bits[1] == 0 and syndrome_bits[2] == 0:
        error_type = "bit_flip"
        error_qubit = 0  # Simplified
    elif syndrome_bits[0] == 0 and syndrome_bits[1] == 1 and syndrome_bits[2] == 0:
        error_type = "bit_flip"
        error_qubit = 1  # Simplified
    elif syndrome_bits[0] == 0 and syndrome_bits[1] == 0 and syndrome_bits[2] == 1:
        error_type = "bit_flip"
        error_qubit = 2  # Simplified
    elif syndrome_bits[3] == 1:  # Phase error
        error_type = "phase_flip"
        error_qubit = 0  # Simplified
    else:
        error_type = "both"
        error_qubit = 0  # Simplified

    A hardware run needs either a linked calibration snapshot with
    calibration_completeness=physical, or the backend_generation must be
    'simulator'.
    """
    issues = []
    for entry in catalog.entries:
        if entry.artifact_type == "calibration":
            continue
        if not entry.data_path:
            continue
        data_path = Path(entry.data_path)
        if data_path.suffix != ".json":
            continue
        try:
            with open(data_path, encoding="utf-8") as f:
                data = json.load(f)

            backend_gen = data.get("backend_generation", "unknown")
            # Simulators don't need physical calibration
            if backend_gen == "simulator":
                continue

            cal_id = data.get("calibration_snapshot_id")
            if not cal_id:
                # Check if calibration exists in the corpus
                cal_found = False
                for e in catalog.entries:
                    if e.artifact_type == "calibration" and e.artifact_id == cal_id:
                        cal_path = Path(e.data_path)
                        if cal_path.exists():
                            with open(cal_path, encoding="utf-8") as cf:
                                cal_data = json.load(cf)
                            if cal_data.get("calibration_completeness") == "physical":
                                cal_found = True
                        break
                if not cal_found:
                    issues.append({
                        "artifact_id": entry.artifact_id,
                        "source_project": entry.source_project,
                        "backend": data.get("backend", "unknown"),
                        "backend_generation": backend_gen,
                        "calibration_snapshot_id": cal_id or "(none)",
