def _identify_threats(
    self,
    qber: float,
    fidelity: float,
    noise_factor: float,
    channel_length: float,
    dd_loops: int,
    tomography_states: int,
    key_timeout: float,
) -> list[ThreatAssessment]:
    """Identify active threats based on parameters."""
    threats = []

    # Beam splitter bias (always present in this system)
    threats.append(self.KNOWN_THREATS["beam_splitter_bias"])

    # Tidal thermal drift (high for long channels)
    if channel_length > 10:
        threats.append(self.KNOWN_THREATS["tidal_thermal_drift"])

    # Tomography undersampling
    if tomography_states < 50000:
        threats.append(self.KNOWN_THREATS["tomography_undersampling"])

    # Key exchange timeout
    if key_timeout > 100:
        threats.append(self.KNOWN_THREATS["key_exchange_timeout"])

    # PNS attack (mitigated by decoy states)
    threats.append(self.KNOWN_THREATS["photon_number_splitting"])

    # Detector efficiency mismatch
    if qber > 0.06:
        threats.append(self.KNOWN_THREATS["detector_efficiency_mismatch"])

    return threats

