        recommendations.append("Increase DD loop count for better noise suppression")
        recommendations.append(
            "Increase tomography sample size for better state reconstruction"
        )

    if overall_score < 70:
        recommendations.append("Consider reducing channel length or improving fiber quality")
        recommendations.append("Implement additional privacy amplification")

    return recommendations

