(function buildBloch() {
  const SVG_NS = 'http://www.w3.org/2000/svg';

  // Project (x,y,z) onto 2D with tilt
  function project(x, y, z) {
    // Tilt: look from above-front (rotate around x-axis by 0.4363 rad)
    const tilt = 0.4363;
    const y2 =  y * Math.cos(tilt) - z * Math.sin(tilt);
    const z2 =  y * Math.sin(tilt) + z * Math.cos(tilt);
    // Perspective
    const f  = 180 / (180 + z2 * 0.9);
    return { px: x * f * R, py: -y2 * f * R };
  }

  const dotsG = document.getElementById('blochDots');

  states.forEach(s => {
    // Cartesian on unit sphere
    const sx = Math.sin(s.theta) * Math.cos(s.phiWrap);
    const sy = Math.sin(s.theta) * Math.sin(s.phiWrap);
    const sz = Math.cos(s.theta);  // = s.z

      const d = document.createElementNS(SVG_NS, 'circle');
