      d.addEventListener('mousemove', moveTip);
      d.addEventListener('mouseleave', hideTip);
      dotsG.appendChild(d);
    });

    // Spiral highlight: connect states in order (dashed guide line)
    const path = document.createElementNS(SVG_NS, 'path');
    const pts  = states.map((s, i) => {
      const sx = Math.sin(s.theta) * Math.cos(s.phiWrap);
      const sy = Math.sin(s.theta) * Math.sin(s.phiWrap);
      const sz = Math.cos(s.theta);
      const { px, py } = project(sx, sy, sz);
      return (i === 0 ? 'M' : 'L') + px.toFixed(1) + ',' + py.toFixed(1);
    });
    path.setAttribute('d', pts.join(' '));
