            model=model,
            system=system_prompt,
            timeout=timeout,
        )
        raw_output = result.stdout
        output = strip_thinking(raw_output) if raw_final_only else raw_output
        output = _normalize_agent_stage_output(output)
        stage_payload = {
            "agent": agent_profile.metatron_agent,
