def shannon_entropy_bits(
    probability_distribution: "numpy.ndarray | list[float]", base: float = 2.0
) -> float:
    """Shannon entropy of a probability distribution in bits (base 2).

    Uses GRE's implementation when available for consistency with the fractal
    walk pipeline; falls back to pure Python otherwise.

    Args:
        probability_distribution: Array of probabilities summing to 1.
        base: Logarithm base (default 2.0 = bits).

    Returns:
        Shannon entropy in the given base.
    """
    if _GRE_ENTROPY_AVAILABLE:
        import numpy as np
        arr = np.asarray(probability_distribution, dtype=np.float64)
        return float(_gre_shannon(arr, base=base))

    import numpy as np
    arr = np.asarray(probability_distribution, dtype=np.float64)
    H = 0.0
    for p in arr:
        if p > 0:
            H -= p * math.log(p, base)
    return float(H)


def von_neumann_entropy_mixed(
    probability_distribution: "numpy.ndarray | list[float]",
) -> float:
    """Von Neumann entropy of a mixed state described by diagonal probabilities.

    Uses GRE's implementation when available; falls back to pure Python
    by constructing a diagonal density matrix.

    Args:
        probability_distribution: Diagonal probability vector.

    Returns:
        Von Neumann entropy in bits.
    """
    if _GRE_ENTROPY_AVAILABLE:
        import numpy as np
        arr = np.asarray(probability_distribution, dtype=np.float64)
        return float(_gre_vn(arr))

    import numpy as np
    arr = np.asarray(probability_distribution, dtype=np.float64)
    H = 0.0
    for p in arr:
        if p > 0:
            H -= p * math.log2(p)
    return float(H)


