def _compute_entropy(evals):
    """Von Neumann entropy of eigenvalue distribution: H = -sum(p_i log2 p_i)."""
    evals = np.abs(evals)
    total = evals.sum()
    if total == 0:
        return 0.0
    p = evals / total
    p = p[p > 0]
    return float(-np.sum(p * np.log2(p)))


def _rank_by_metric_angle(results, metric, higher=True):
    """Return [(angle, value)] ranked by metric across all results, highest first."""
    from collections import defaultdict
    by_angle = defaultdict(list)
    for r in results:
        angle = r["angle"]
        if metric == "spec_gap":
            v = r.get("resonance_descriptor", {}).get("spectral_gap")
        elif metric == "ev_spacing":
            v = r.get("resonance_descriptor", {}).get("eigenvalue_spacing_ratio")
        elif metric == "evphase_spacing":
            v = r.get("resonance_descriptor", {}).get("eigenphase_spacing_ratio")
        elif metric == "part_ratio":
            v = r.get("attractor_signature", {}).get("participation_ratio_final")
        elif metric == "transfer_fid":
            v = r.get("state_transfer_fidelity")
        elif metric == "optimal_steps":
            v = r.get("optimal_transfer_steps")
        else:
            v = None
        if v is not None:
            by_angle[angle].append(v)

    pairs = []
    for angle, vals in by_angle.items():
        pairs.append((angle, float(np.mean(vals))))
    return sorted(pairs, key=lambda x: x[1], reverse=higher)


