def get_available_ibm_archive_jobs(
    archive_dir: str | Path | None = None,
) -> list[IBMArchiveJobSummary]:
    """List normalized summaries for all paired IBM archive jobs."""
    resolved_dir = resolve_ibm_archive_dir(archive_dir)
    summaries = []
    for job_id in _extract_job_ids(resolved_dir):
        info_data = _load_json(resolved_dir / f"job-{job_id}-info.json")
        result_data = _load_json(resolved_dir / f"job-{job_id}-result.json")
        summaries.append(_build_job_summary(job_id, info_data, result_data))

def _extract_result_payload(result_data: dict[str, Any]) -> Any:
    first_entry = result_data.get("data", [{}])
    if isinstance(first_entry, list) and first_entry:
        first_entry = first_entry[0]
    else:
        first_entry = {}
    return first_entry.get("results", {}).get("c", {})

def _extract_info_circuit(info_data: dict[str, Any]) -> Any:
    items = info_data.get("params", {}).get("quantum_program", {}).get("items", [])
    if not items:
        return {}
    return items[0].get("circuit", {})


def extract_ibm_archive_counts(result_data: dict[str, Any]) -> dict[str, int]:
    """Extract replayable measurement counts from an IBM archive result payload.

    Supported formats:
    - explicit ``counts`` mapping in the payload
    - ``memory`` list of bitstrings
    - ``data`` list of bitstrings or bit rows when dtype is bool

    Encoded binary payloads are intentionally not decoded here because the archive format
    may vary; callers should supply decoded data if available.
    """
    result_payload = _extract_result_payload(result_data)

    counts_payload = result_payload.get("counts")
    if isinstance(counts_payload, dict):
        return {str(key): int(value) for key, value in counts_payload.items()}

    memory_payload = result_payload.get("memory")
    if isinstance(memory_payload, list):
        return _counts_from_memory_rows(memory_payload)

    data_payload = result_payload.get("data")
    if isinstance(data_payload, list):
        return _counts_from_memory_rows(data_payload)

    dtype = result_payload.get("dtype")
    if dtype == "bool" and isinstance(data_payload, str):
        raise ValueError(
            "IBM archive result payload uses encoded boolean data; decoded shot memory or counts are required for replay"
        )

    raise ValueError("IBM archive result payload does not contain replayable counts")


def load_ibm_archive_payloads(
    job_id: str, archive_dir: str | Path | None = None
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Load the raw info/result payload pair for one IBM archive job."""
    resolved_dir = resolve_ibm_archive_dir(archive_dir)
    _validate_job_id(job_id)
    info_path = resolved_dir / f"job-{job_id}-info.json"
    result_path = resolved_dir / f"job-{job_id}-result.json"

    if not info_path.exists() or not result_path.exists():
        raise KeyError(f"Unknown IBM archive job: {job_id}")

    return _load_json(info_path), _load_json(result_path)


def _build_job_summary(
    job_id: str, info_data: dict[str, Any], result_data: dict[str, Any]
) -> IBMArchiveJobSummary:
    circuit_metadata = _extract_info_circuit(info_data)
    result_payload = _extract_result_payload(result_data)
    result_shape = result_payload.get("shape") or []

    # Safely convert shape elements to int, handling malformed data
    try:
        shots = int(result_shape[0]) if len(result_shape) >= 1 else None
    except (ValueError, TypeError):
        shots = None

    try:
        classical_bits = int(result_shape[1]) if len(result_shape) >= 2 else None
    except (ValueError, TypeError):
        classical_bits = None

    # Safely convert full shape array
    safe_shape = []
    for value in result_shape:
