def resolve_ibm_archive_dir(archive_dir: str | Path | None = None) -> Path:
    """Resolve archive directory from parameter or environment."""
    candidate = archive_dir or os.environ.get("QPYTH_IBM_ARCHIVE_DIR")
    if not candidate:
        raise ValueError(
            "IBM archive directory is required. Pass archive_dir or set QPYTH_IBM_ARCHIVE_DIR."
        )

    path = Path(candidate).expanduser().resolve()
    if not path.exists() or not path.is_dir():
        raise FileNotFoundError(f"IBM archive directory not found: {path}")

    return path


def _load_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def _counts_from_memory_rows(rows: list[Any]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for row in rows:
        if isinstance(row, str):
            bitstring = row.replace(" ", "")
        elif isinstance(row, (list, tuple)):
            try:
                bitstring = "".join("1" if int(value) else "0" for value in row)
            except (TypeError, ValueError) as exc:
                raise ValueError("IBM archive row contains non-binary values") from exc
        else:
            raise ValueError("IBM archive row must be a bitstring or sequence of bits")

        counts[bitstring] = counts.get(bitstring, 0) + 1
    return counts


def _validate_job_id(job_id: str) -> None:
    if len(job_id) > MAX_IBM_ARCHIVE_JOB_ID_LENGTH:
        raise ValueError(
            f"job_id '{job_id}' exceeds {MAX_IBM_ARCHIVE_JOB_ID_LENGTH} characters"
        )

    if not re.fullmatch(r"[A-Za-z0-9](?:[A-Za-z0-9_-]*[A-Za-z0-9])?", job_id):
        raise ValueError(f"job_id '{job_id}' contains invalid characters")


def _extract_job_ids(archive_dir: Path) -> list[str]:
    job_ids = set()
    for path in archive_dir.glob("job-*-info.json"):
        suffix = path.name.removeprefix("job-").removesuffix("-info.json")
        if (archive_dir / f"job-{suffix}-result.json").exists():
            job_ids.add(suffix)
    return sorted(job_ids)

