def _load_library_records() -> list[DNASequenceRecord]:
    registry = _read_json(_sequence_data_dir() / "dna_sequence_registry.json")
    records = []
    for entry in registry.get("records", []):
        records.append(
            DNASequenceRecord(
                record_id=str(entry["record_id"]),
                sequence=str(entry["sequence"]),
                length=int(entry["length"]),
                source="library",
                gc_content=float(entry["gc_content"]),
                phi_coherence=float(entry["phi_coherence"]),
                metadata={
                    "mean_frequency": entry.get("mean_frequency"),
                    "structured_entropy": entry.get("structured_entropy"),
                },
            )
        )
    return records


def get_available_dna_sequences() -> list[DNASequenceRecord]:
    """Return curated DNA-inspired sequence blueprint and registry records."""
    return [_load_blueprint_record(), *_load_library_records()]


def get_dna_sequence(record_id: str) -> DNASequenceRecord:
