def get_dna_circuit_preview(circuit_id: str, max_lines: int = 12) -> str:
    """Return a lightweight QASM preview for UI and CLI use."""
    asset = _get_asset(circuit_id)
    qasm_path = validate_qasm_file(_data_dir() / asset.qasm_file)
    lines = qasm_path.read_text(encoding="utf-8").splitlines()
    return "\n".join(lines[:max_lines])

    if version.startswith("2"):
        return QuantumCircuit.from_qasm_str(qasm_text)

    if version.startswith("3"):
        try:
            import qiskit.qasm3 as qasm3  # type: ignore

            return qasm3.loads(qasm_text)
        except MissingOptionalLibraryError as e:
            raise RuntimeError(
                "OpenQASM 3 import requires 'qiskit_qasm3_import'. Install with: pip install qiskit_qasm3_import"
            ) from e

    raise ValueError(f"Unsupported OpenQASM version: {version}")


def validate_qasm_file(qasm_path: str | Path) -> Path:
    """Validate that a QASM file exists and contains parseable content."""
    path = Path(qasm_path)
    if not path.exists():
        raise FileNotFoundError(f"DNA circuit file not found: {path}")

    text = path.read_text(encoding="utf-8").strip()
    if not text:
        raise ValueError(f"DNA circuit file is empty: {path}")

    if not text.startswith("OPENQASM"):
        raise ValueError(f"DNA circuit file is not valid OpenQASM: {path}")

    return path


def load_qasm_circuit_file(qasm_path: str | Path) -> QuantumCircuit:
    """Load a QASM file with version-aware parsing."""
    path = validate_qasm_file(qasm_path)
    qasm_text = path.read_text(encoding="utf-8")
    return _load_qasm_circuit_text(qasm_text)


def get_available_dna_circuit_ids() -> list[str]:
    """Return curated DNA-inspired circuit ids."""
    return sorted(DNA_CIRCUIT_ASSETS)


def load_dna_circuit_metadata(circuit_id: str) -> dict[str, Any]:
    """Load raw metadata for a bundled DNA-inspired circuit."""
    asset = _get_asset(circuit_id)
    metadata_path = _data_dir() / asset.metadata_file
    if not metadata_path.exists():
        raise FileNotFoundError(f"DNA metadata file not found: {metadata_path}")
    return _read_json(metadata_path)


def load_dna_circuit(circuit_id: str) -> QuantumCircuit:
    """Load a bundled DNA-inspired OpenQASM circuit into Qiskit."""
    asset = _get_asset(circuit_id)
    return load_qasm_circuit_file(_data_dir() / asset.qasm_file)


def _count_measurements(circuit: QuantumCircuit) -> int:
    return sum(instruction.operation.name == "measure" for instruction in circuit.data)


def summarize_dna_circuit(circuit_id: str) -> DNACircuitSummary:
    """Build a normalized summary for a bundled DNA-inspired circuit."""
    asset = _get_asset(circuit_id)
    metadata = load_dna_circuit_metadata(circuit_id)
    qasm_path = validate_qasm_file(_data_dir() / asset.qasm_file)
    qasm_text = qasm_path.read_text(encoding="utf-8")
    circuit = _load_qasm_circuit_text(qasm_text)

    config = metadata.get("config", {})
    sequences = metadata.get("sequences", {})

    return DNACircuitSummary(
        circuit_id=asset.circuit_id,
        name=asset.name,
        description=asset.description,
        base_pairs=int(config.get("base_pairs", 0)),
        helix_turns=float(config.get("helix_turns", 0.0)),
        qubits=int(metadata.get("qubits", circuit.num_qubits)),
        measured_qubits=_count_measurements(circuit),
        source_gate_count=int(metadata.get("total_gates", 0)),
        source_depth=int(metadata.get("circuit_depth", 0)),
        parsed_gate_count=circuit.size(),
        parsed_depth=int(circuit.depth() or 0),
        qasm_version=_extract_qasm_version(qasm_text),
        source_type=asset.source_type,
        sequences=dict(sequences),
        geometry=dict(metadata.get("geometry", {})),
    )


def get_available_dna_circuits() -> list[DNACircuitSummary]:
    """Return normalized summaries for all curated DNA-inspired circuit assets."""
    return [
        summarize_dna_circuit(circuit_id)
        for circuit_id in get_available_dna_circuit_ids()
    ]

