import { describe, it, expect } from 'vitest';
import {
  calculateProcessFidelity,
  calculateQBER,
  calculateSecurityScore,
  assessThreatLevel,
  formatMetric,
  getMetricColor,
  simulateFidelityOverTime,
} from './quantum';

describe('calculateProcessFidelity', () => {
  it('matches the backend default calibration result', () => {
    const fidelity = calculateProcessFidelity(0.895, 16, 1.5, 15000);
    expect(fidelity).toBeGreaterThan(0.8);
    expect(fidelity).toBeLessThan(0.95);
  });

  it('increases with more DD loops', () => {
    const low = calculateProcessFidelity(0.895, 4, 1.0, 15000);
    const high = calculateProcessFidelity(0.895, 32, 1.0, 15000);
    expect(high).toBeGreaterThan(low);
  });

  it('decreases with higher noise factor', () => {
    const lowNoise = calculateProcessFidelity(0.895, 16, 1.0, 15000);
    const highNoise = calculateProcessFidelity(0.895, 16, 2.5, 15000);
    expect(highNoise).toBeLessThan(lowNoise);
  });

  it('increases with more tomography states', () => {
    const low = calculateProcessFidelity(0.895, 16, 1.0, 15000);
    const high = calculateProcessFidelity(0.895, 16, 1.0, 200000);
    expect(high).toBeGreaterThan(low);
  });

  it('clamps to physical bounds', () => {
    expect(calculateProcessFidelity(0.99, 100, 1.0, 1_000_000)).toBeLessThanOrEqual(0.9999);
    expect(calculateProcessFidelity(0.1, 1, 5.0, 100)).toBeGreaterThanOrEqual(0.5);
  });
});

describe('calculateQBER', () => {
  it('matches the backend default calibration result', () => {
    const qber = calculateQBER(0.089, 1e-6, 15);
    expect(qber).toBeGreaterThan(0.08);
    expect(qber).toBeLessThan(0.1);
  });

  it('increases with channel length', () => {
    const short = calculateQBER(0.05, 1e-6, 1);
    const long = calculateQBER(0.05, 1e-6, 100);
    expect(long).toBeGreaterThan(short);
  });

  it('increases with dark count rate', () => {
    const low = calculateQBER(0.05, 1e-9, 15);
    const high = calculateQBER(0.05, 1e-3, 15);
    expect(high).toBeGreaterThan(low);
  });

  it('is clamped between 0.01 and 0.5', () => {
    expect(calculateQBER(0.0, 0, 0)).toBe(0.01);
    expect(calculateQBER(1.0, 1, 1000)).toBe(0.5);
  });
});

describe('calculateSecurityScore', () => {
  it('returns a high score for ideal parameters', () => {
    const score = calculateSecurityScore(0.99, 0.01, 1.0, 1.0);
    expect(score).toBeGreaterThan(80);
  });

  it('returns a low score for poor parameters', () => {
    const score = calculateSecurityScore(0.5, 0.2, 2.0, 0.0);
    expect(score).toBeLessThan(50);
  });
});

describe('assessThreatLevel', () => {
  it('classifies low risk correctly', () => {
    expect(assessThreatLevel(0.04, 1.1)).toBe('LOW');
  });

  it('classifies critical risk correctly', () => {
    expect(assessThreatLevel(0.15, 2.0)).toBe('CRITICAL');
  });
});

