  it('formats fidelity as percentage', () => {
    expect(formatMetric(0.895, 'fidelity')).toBe('89.50%');
  });

  it('formats qber as percentage', () => {
    expect(formatMetric(0.089, 'qber')).toBe('8.90%');
  });

  it('formats noise factor with x suffix', () => {
    expect(formatMetric(1.5, 'noise')).toBe('1.50x');
  });
});

