import { useState, useEffect, useCallback } from 'react';
import {
  QuantumState,
  CalibrationSettings,
  INITIAL_QUANTUM_STATE,
  INITIAL_CALIBRATION,
} from '../models/quantum';
import * as api from '../api/client';
import { calculateProcessFidelity, calculateQBER } from '../utils/quantum';

const API_POLL_INTERVAL_MS = 5000;

export function useQuantumState() {
  const [state, setState] = useState<QuantumState>(INITIAL_QUANTUM_STATE);
  const [calibration, setCalibration] = useState<CalibrationSettings>(INITIAL_CALIBRATION);
  const [isCalibrating, setIsCalibrating] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [useBackend, setUseBackend] = useState(true);

  // Load initial state from backend
  useEffect(() => {
    if (!useBackend) return;

    let cancelled = false;
    api
      .getState()
      .then((initialState) => {
        if (cancelled) return;
        setState(initialState);
        setCalibration({
          ddLoops: initialState.ddLoops,
          noiseFactor: initialState.noiseFactor,
          tomographyRate: initialState.tomographyStates,
          timeoutPolicy: initialState.keyExchangeTimeout,
          dynamicBranchesEnabled: true,
        });
        setError(null);
      })
      .catch((err) => {
        if (cancelled) return;
        console.warn('Backend unavailable, using local simulation:', err);
        setError('Backend API unavailable; running in local simulation mode.');
        setUseBackend(false);
      });

    return () => {
      cancelled = true;
    };
  }, [useBackend]);

  // Periodically refresh state from backend
  useEffect(() => {
    if (!useBackend) return;

    const interval = setInterval(() => {
      api
        .getState()
        .then(setState)
        .catch((err) => {
          console.warn('State poll failed:', err);
        });
    }, API_POLL_INTERVAL_MS);

    return () => clearInterval(interval);
  }, [useBackend]);

  const recalibrate = useCallback(async () => {
    setIsCalibrating(true);
    setError(null);

    try {
      if (useBackend) {
        const updatedState = await api.recalibrate();
        setState(updatedState);
      } else {
        // Local fallback simulation
        await new Promise((resolve) => setTimeout(resolve, 1500));
        setState((prev) => ({
          ...prev,
          ddLoops: calibration.ddLoops,
          noiseFactor: calibration.noiseFactor,
          tomographyStates: calibration.tomographyRate,
          keyExchangeTimeout: calibration.timeoutPolicy,
          processFidelity: calculateProcessFidelity(
            0.895,
            calibration.ddLoops,
            calibration.noiseFactor,
            calibration.tomographyRate
          ),
          qber: calculateQBER(0.089, prev.darkCountRate, prev.channelLength),
        }));
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      setError(`Recalibration failed: ${message}`);
    } finally {
      setIsCalibrating(false);
    }
  }, [calibration, useBackend]);

  const updateCalibration = useCallback(
    async (updates: Partial<CalibrationSettings>) => {
      const nextCalibration = { ...calibration, ...updates };
      setCalibration(nextCalibration);

      if (!useBackend) return;

      try {
        const result = await api.updateCalibration(updates);
        setState(result.state);
        setCalibration(result.calibration);
        setError(null);
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        setError(`Calibration update failed: ${message}`);
      }
    },
    [calibration, useBackend]
  );

  const updateState = useCallback((updates: Partial<QuantumState>) => {
    setState((prev) => ({ ...prev, ...updates }));
  }, []);

  const resetBackendMode = useCallback(() => {
    setUseBackend(true);
    setError(null);
  }, []);

  return {
    state,
    calibration,
    isCalibrating,
    error,
    useBackend,
    recalibrate,
    updateCalibration,
    updateState,
    resetBackendMode,
  };
}

