def main():
    import argparse
    parser = argparse.ArgumentParser(description="Backfill lambda2 into corpus artifacts")
    parser.add_argument("--dry-run", action="store_true")
    args = parser.parse_args()

    if args.dry_run:
        _dry_run()
    else:
        process_all()


def _dry_run():
    print("Nodes lookup table:")
