import { useState, useEffect, useCallback } from 'react';
import { TelemetryData } from '../models/quantum';
import { connectTelemetry, getTelemetry } from '../api/client';
import { generateTelemetryData } from '../utils/quantum';

const FALLBACK_STATE = {
  processFidelity: 0.895,
  goalFidelity: 0.9703,
  baselineRange: [0.77, 0.92] as [number, number],
  qber: 0.089,
  darkCountRate: 1e-6,
  channelLength: 15,
  ddLoops: 16,
  noiseFactor: 1.5,
  tomographyStates: 15000,
  keyExchangeTimeout: 250,
  targetTimeout: 50,
};

export function useTelemetry(maxDataPoints: number = 50, useBackend: boolean = true) {
  const [data, setData] = useState<TelemetryData[]>([]);
  const [isLive, setIsLive] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Load recent history when backend becomes available
  useEffect(() => {
    if (!useBackend) return;

    let cancelled = false;
    getTelemetry(maxDataPoints)
      .then((history) => {
        if (cancelled) return;
        setData(history);
        setError(null);
      })
      .catch((err) => {
        if (cancelled) return;
        console.warn('Failed to load telemetry history:', err);
      });

    return () => {
      cancelled = true;
    };
  }, [useBackend, maxDataPoints]);

  // WebSocket live stream
  useEffect(() => {
    if (!useBackend || !isLive) return;

    setError(null);
    const disconnect = connectTelemetry(
      (point) => {
        setData((prev) => {
          const updated = [...prev, point];
          return updated.slice(-maxDataPoints);
        });
      },
      () => {
        setError('Telemetry WebSocket disconnected. Falling back to local simulation.');
      }
    );

    return () => disconnect();
  }, [useBackend, isLive, maxDataPoints]);

  // Local fallback simulation when backend is disabled or unavailable
  useEffect(() => {
    if (useBackend || !isLive) return;

    const interval = setInterval(() => {
      setData((prev) => {
        const newPoint = generateTelemetryData(FALLBACK_STATE);
        const updated = [...prev, newPoint];
        return updated.slice(-maxDataPoints);
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [useBackend, isLive, maxDataPoints]);

  const toggleLive = useCallback(() => setIsLive((prev) => !prev), []);
  const clearData = useCallback(() => setData([]), []);

  return { data, isLive, toggleLive, clearData, error };
}

