As mentioned earlier we can also simplify QNode objects to, for example, group rotation gates:

dev = qp.device("default.qubit", wires=2)

@qp.simplify
    @qp.qnode(dev)
    def circuit(x):
        (
            qp.RX(x[0], wires=0)
            @ qp.RY(x[1], wires=1)
            @ qp.RZ(x[2], wires=2)
            @ qp.RX(-1, wires=0)
            @ qp.RY(-2, wires=1)
            @ qp.RZ(2, wires=2)
        )
