            qp.RX(phi[0], wires=0)
            qp.RZ(phi[1], wires=1)
            qp.CNOT(wires=[0, 1])
            qp.RX(theta, wires=0)
            return qp.sample() # Here, we take samples instead.

return circuit(phi, theta)

