@qp.set_shots(shots=None)
        @qp.qnode(dev, interface='torch', diff_method='backprop')
        def circuit(x):
            qp.RX(x[0], wires=0)
            return qp.state()

x = torch.tensor([0.1], requires_grad=True, dtype=torch.complex64)
        print(torch.autograd.functional.jacobian(circuit, (x,)))

In PennyLane, samples are drawn from the eigenvalues of an observable, or from the
computational basis states if no observable is provided. This process is not differentiable
in general, so no gradient flow backwards through the sampling is allowed.

Currently, attempting to compute the gradient in this scenario will not raise an
error, but the results will be incorrect:

def sample_backward():
        dev = qp.device('default.qubit', wires=1)

@qp.set_shots(shots=5)
        @qp.qnode(dev)
        def circuit(x):
            qp.RX(x[0], wires=0)
            return qp.sample(wires=0)

import pennylane as qp
    import jax.numpy as jnp

dev = qp.device('lightning.qubit', wires=1)

@qp.qjit(capture=True)
    def workflow(x):

@qp.qnode(dev, diff_method="adjoint")
        def circuit(_x):
            qp.RX(_x, wires=0)
            return qp.expval(qp.Z(0))

return qp.grad(circuit)(x)

>>> x = jnp.array(jnp.pi / 4)
>>> workflow(x)
Array(-0.70710678, dtype=float64)

Valid JAX data types 
--------------------

@qp.qjit(capture=True)
    @qp.qnode(dev)
    def circuit():
        qp.QubitUnitary(my_unitary, wires=0)
        return qp.state()

>>> circuit()
...
TypeError: Argument '[[1, 0], [0, 1]]' of type '<class 'list'>' is not a valid JAX type

But a list can be passed to qp.QubitUnitary as a keyword argument:

import pennylane as qp

my_unitary = [[1, 0], [0, 1]]

dev = qp.device('lightning.qubit', wires=2)

@qp.qjit(capture=True)
    @qp.qnode(dev)
    def circuit():
        qp.QubitUnitary(U=my_unitary, wires=0)
        return qp.state()

@qp.qjit(capture=True)
    @qp.qnode(dev)
    def circuit(angle):
        qp.RX(phi=angle, wires=0)
        return qp.expval(qp.Z(0))

>>> angle = jnp.array(0.1)
>>> circuit(angle)
...
InvalidInputException: Argument 'JitTracer<~float64[]>' of type <class 'jax._src.interpreters.partial_eval.DynamicJaxprTracer'> is not a valid JAX type.

Even though the value for phi in RZ is given as a valid JAX type, the 
fact that it was provided as a keyword argument results in an error.

But, when the angle is passed as a positional argument, the circuit executes as 
expected:

import pennylane as qp
    import jax.numpy as jnp

dev = qp.device("lightning.qubit", wires=1)

@qp.qjit(capture=True)
    @qp.qnode(dev)
    def circuit(angle):
        qp.RX(angle, wires=0)
        return qp.expval(qp.Z(0))

>>> angle = jnp.array(0.1)
>>> circuit(angle)
Array(0.9950042, dtype=float32)

